typedef struct logger logger_t;
struct logger { void (*log)(logger_t *self, const char *msg); };

static void null_log(logger_t *self, const char *msg) { (void)self; (void)msg; }

static logger_t NULL_LOGGER = { .log = null_log };   /* one shared instance */

void run(logger_t *lg) { lg->log(lg, "starting"); }  /* never NULL-checked */
